<script setup lang="ts">
import { nextTick, onMounted, ref } from 'vue';
import { fetchComments, postComment } from '@/entities/comment/comment.api';
import { formatRelative, formatCount } from '@/shared/lib/format';
import { haptics } from '@/shared/lib/telegram';
import type { CommentItem } from '@/shared/api/types';

const props = defineProps<{ titleId: number; highlightId?: number | null }>();

const comments = ref<CommentItem[]>([]);
const loading = ref(false);
const done = ref(false);
const error = ref<string | null>(null);
const draft = ref('');
const posting = ref(false);
const replyTo = ref<{ id: number; authorName: string } | null>(null);
const highlighted = ref<number | null>(null);
let cursor: string | undefined;

async function load(): Promise<void> {
  if (loading.value || done.value) return;
  loading.value = true;
  try {
    const page = await fetchComments(props.titleId, cursor);
    comments.value.push(...page.items);
    cursor = page.nextCursor ?? undefined;
    if (!page.nextCursor) done.value = true;
  } catch (e) {
    error.value = e instanceof Error ? e.message : 'Помилка';
  } finally {
    loading.value = false;
  }
}

async function submit(): Promise<void> {
  const body = draft.value.trim();
  if (!body || posting.value) return;
  posting.value = true;
  try {
    const created = await postComment(props.titleId, body, replyTo.value?.id ?? null);
    comments.value.unshift(created);
    draft.value = '';
    replyTo.value = null;
    haptics.success();
  } catch (e) {
    error.value = e instanceof Error ? e.message : 'Не вдалося надіслати';
  } finally {
    posting.value = false;
  }
}

function startReply(c: CommentItem): void {
  replyTo.value = { id: c.id, authorName: c.user.firstName };
  haptics.select();
}

function jumpTo(id: number): void {
  const el = document.getElementById(`comment-${id}`);
  if (!el) return;
  el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  highlighted.value = id;
  window.setTimeout(() => (highlighted.value = null), 2000);
}

onMounted(async () => {
  await load();
  if (props.highlightId) {
    await nextTick();
    jumpTo(props.highlightId);
  }
});
</script>

<template>
  <section class="comments">
    <h2 class="comments__title">Коментарі</h2>

    <!-- Composer -->
    <div class="composer">
      <div v-if="replyTo" class="composer__reply">
        <span class="mono">Відповідь для {{ replyTo.authorName }}</span>
        <button type="button" @click="replyTo = null">✕</button>
      </div>
      <div class="composer__row">
        <textarea
          v-model="draft"
          class="composer__input"
          rows="1"
          placeholder="Додати коментар…"
          @keydown.enter.exact.prevent="submit"
        />
        <button
          class="composer__send"
          type="button"
          :disabled="posting || !draft.trim()"
          @click="submit"
        >
          ➤
        </button>
      </div>
    </div>

    <p v-if="error" class="comments__error">{{ error }}</p>

    <ul class="comments__list">
      <li
        v-for="c in comments"
        :id="`comment-${c.id}`"
        :key="c.id"
        class="comment"
        :class="{ 'is-highlighted': highlighted === c.id }"
      >
        <div class="comment__avatar">
          <img v-if="c.user.photoUrl" :src="c.user.photoUrl" :alt="c.user.firstName" />
          <span v-else>{{ c.user.firstName.charAt(0) }}</span>
          <i v-if="c.user.online" class="comment__online" aria-label="онлайн" />
        </div>
        <div class="comment__body">
          <div class="comment__head">
            <span class="comment__author">{{ c.user.firstName }}</span>
            <span class="comment__count mono">{{ formatCount(c.user.commentsCount) }} комент.</span>
            <span class="comment__time mono">{{ formatRelative(c.createdAt) }}</span>
          </div>
          <button v-if="c.parent" class="comment__quote" type="button" @click="jumpTo(c.parent.id)">
            <span class="comment__quote-author">{{ c.parent.authorName }}</span>
            <span class="comment__quote-text">{{ c.parent.excerpt }}</span>
          </button>
          <p class="comment__text">{{ c.body }}</p>
          <button class="comment__reply" type="button" @click="startReply(c)">Відповісти</button>
        </div>
      </li>
    </ul>

    <button v-if="!done" class="comments__more" type="button" :disabled="loading" @click="load">
      {{ loading ? 'Завантаження…' : 'Показати ще' }}
    </button>
    <p v-else-if="comments.length === 0" class="comments__empty">
      Ще немає коментарів. Будьте першим!
    </p>
  </section>
</template>

